/// <summary>
/// Update information when is creating or updating IndustryKeyValue
/// </summary>
/// <param name = "_entityCtx">data entity inserted or updated</param>
public void persistEntity(DataEntityRuntimeContext _entityCtx)
{
    TAMRebateAndDeductionsAgreementDealEntity entity = _entityCtx.getEntityRecord();
    TAMRebateDeal  rebateDeal;
    METIndustryKeyTable industryKeyTable;

    if (entity.METIndustryKey)
    {
        select firstonly industryKeyTable
            where industryKeyTable.IndustryKey == entity.METIndustryKey;

        if (industryKeyTable.RecId != 0)
        {
            ttsbegin;
            select forupdate rebateDeal
                where rebateDeal.Deal == entity.DealNumber;
            if (rebateDeal.RecId != 0)
            {
                rebateDeal.METIndustryKeyId = industryKeyTable.RecId;
                rebateDeal.update();
            }
            ttscommit;
        }
    }
    next persistEntity(_entityCtx);

}
